// Generated by `just generate` from `src/kernel/stamp.ts`. Edit the source and run `just generate`.
// The session stamp: the build of dotclaude that each session starts with (P38).
// The stamp is the text of a `system` notice, which starts with a fixed prefix, so that a reader finds it.
// This file has no import, so every layer and each test can use it.

/** Where the SHA of a stamp comes from: the install record, `git`, or nowhere. */
export const SHA_SOURCES = ["install", "git", "unknown"] as const;

/** One source of a SHA, from `SHA_SOURCES`. */
export type ShaSource = (typeof SHA_SOURCES)[number];

/** The SHA of a stamp when no source gives one. */
export const UNKNOWN_SHA = "unknown";

/** The build of one session: the dotclaude version, the short commit SHA, where the SHA came from, the session, and the time. */
export type StampRecord = {
  version: string;
  sha: string;
  shaSource: ShaSource;
  sessionId: string;
  at: string;
};

/** The text that starts each stamp, so that a reader finds the stamp in the transcript. */
export const STAMP_PREFIX = "dotclaude build stamp: ";

/**
 * The text of the notice for `record`: the prefix, then the record as JSON.
 * `formatStamp` and `parseStamp` are the only pair that writes and reads this text.
 */
export const formatStamp = (record: StampRecord): string =>
  `${STAMP_PREFIX}${JSON.stringify(record)}`;

const isShaSource = (value: unknown): value is ShaSource =>
  SHA_SOURCES.some((source) => source === value);

/**
 * The record of a stamp text, or undefined for any other text.
 * Text with no prefix, text that is not JSON after the prefix, and a record with a field of the wrong type give undefined.
 */
export const parseStamp = (text: unknown): StampRecord | undefined => {
  if (typeof text !== "string" || !text.startsWith(STAMP_PREFIX)) return;
  let value: unknown;
  try {
    value = JSON.parse(text.slice(STAMP_PREFIX.length));
  } catch {
    return;
  }
  if (typeof value !== "object" || value === null) return;
  const { version, sha, shaSource, sessionId, at } = value as Record<
    string,
    unknown
  >;
  if (
    typeof version !== "string" ||
    typeof sha !== "string" ||
    !isShaSource(shaSource) ||
    typeof sessionId !== "string" ||
    typeof at !== "string"
  )
    return;
  return { version, sha, shaSource, sessionId, at };
};
